package co.educontrol.demo;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @Profile("demo") @RequestMapping("/api/demo")
public class PublicationController {
 private final JdbcTemplate db; private final BulkDataService data;
 public PublicationController(JdbcTemplate db,BulkDataService data){this.db=db;this.data=data;}
 List<Map<String,String>> rows(String kind){return db.query("SELECT id,payload,deleted FROM demo_publications WHERE kind=? ORDER BY id",(rs,n)->{var r=data.decode(rs.getString("payload"));r.put("id",rs.getString("id"));r.put("deleted",String.valueOf(rs.getBoolean("deleted")));return r;},kind);}
 Map<String,String> row(String kind,String id){return rows(kind).stream().filter(r->id.equals(r.get("id"))).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 boolean publishedEvent(String id){return data.list("agenda",null).stream().anyMatch(e->id.equals(e.get("codigo_evento"))&&"PUBLICADO".equals(e.get("estado")));}
 @GetMapping("/announcements") public ResponseEntity<List<Map<String,String>>> publicList(){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(rows("announcement").stream().filter(r->"PUBLICADO".equals(r.get("state"))&&"false".equals(r.get("deleted"))).peek(r->{if(db.queryForObject("SELECT COUNT(*) FROM demo_event_images WHERE code=? AND active=TRUE",Integer.class,"PUB-"+r.get("id"))>0)r.put("image","/api/demo/announcements/images/"+r.get("id"));}).toList());}
 @GetMapping("/admin/registration/announcements") public List<Map<String,String>> all(){return rows("announcement");}
 @GetMapping("/event-pages/{id}") public ResponseEntity<Map<String,String>> page(@PathVariable String id){if(!publishedEvent(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);var r=row("event",id);if(!"PUBLICADO".equals(r.get("state")))throw new ResponseStatusException(HttpStatus.NOT_FOUND);var event=data.list("agenda",null).stream().filter(e->id.equals(e.get("codigo_evento"))).findFirst().orElseThrow();r.put("date",event.get("fecha_inicio"));var photos=new ArrayList<String>();for(int i=1;i<=6;i++)if(db.queryForObject("SELECT COUNT(*) FROM demo_event_images WHERE code=? AND active=TRUE",Integer.class,"PHOTO-"+id+"-"+i)>0)photos.add("/api/demo/event-pages/"+id+"/photos/"+i);r.put("photos",data.encode(photos));return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(r);}
 @GetMapping("/admin/registration/event-pages/{id}") public Map<String,String> adminPage(@PathVariable String id){return row("event",id);}
 @PostMapping("/admin/registration/announcements/{id}") @Transactional public Map<String,String> saveAnnouncement(@PathVariable String id,@RequestBody Map<String,String> input,Authentication auth){return save("announcement",id,input,auth);}
 @PostMapping("/admin/registration/event-pages/{id}") @Transactional public Map<String,String> savePage(@PathVariable String id,@RequestBody Map<String,String> input,Authentication auth){if(data.list("agenda",null).stream().noneMatch(e->id.equals(e.get("codigo_evento"))))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return save("event",id,input,auth);}
 private Map<String,String> save(String kind,String id,Map<String,String> input,Authentication auth){
  db.queryForObject("SELECT id FROM demo_data_lock WHERE id=1 FOR UPDATE",Integer.class);
  if(!id.matches("[A-Za-z0-9_-]{1,60}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  var allowed=kind.equals("event")?Set.of("title","intro","place","meeting","cost","recommendations","observations","schedule","album","state","address","mapUrl","date","deadline","points","prices"):Set.of("title","intro","type","link","event","state");var r=new HashMap<String,String>();
  for(String key:allowed){String v=input.getOrDefault(key,"");if(v==null||v.length()>(key.equals("title")?180:key.equals("link")||key.equals("album")?1000:8000))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);r.put(key,v.strip());}
  if(r.get("title").isBlank()||!Set.of("BORRADOR","PUBLICADO").contains(r.get("state")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  for(String key:List.of("link","album","mapUrl"))if(r.containsKey(key)&&!r.get(key).isBlank()&&!BulkDataService.https(r.get(key)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  if(kind.equals("event")){for(String key:List.of("date","deadline"))if(!r.get(key).isBlank())try{java.time.LocalDate.parse(r.get(key));}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST);}validateRows(r.get("points"),true);validateRows(r.get("prices"),false);}
  if(kind.equals("announcement")&&!Set.of("GENERAL","FERIA","NIVELACIONES","SALIDA","ALBUM").contains(r.get("type")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  if(kind.equals("announcement")&&!r.get("event").isBlank()&&data.list("agenda",null).stream().noneMatch(e->r.get("event").equals(e.get("codigo_evento"))))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  if(kind.equals("event")&&!r.get("date").isBlank()){var e=data.list("agenda",null).stream().filter(v->id.equals(v.get("codigo_evento"))).findFirst().orElseThrow();e.put("fecha_inicio",r.get("date"));if(!e.getOrDefault("fecha_fin","").isBlank()&&e.get("fecha_fin").compareTo(r.get("date"))<0)e.put("fecha_fin",r.get("date"));data.saveEvent(id,e,auth.getName());}
  if(db.update("UPDATE demo_publications SET payload=? WHERE kind=? AND id=?",data.encode(r),kind,id)==0)db.update("INSERT INTO demo_publications(kind,id,payload) VALUES (?,?,?)",kind,id,data.encode(r));audit(auth,"EDITAR_PUBLICACION",kind+":"+id);return r;
 }
 @PostMapping("/admin/registration/announcements/{id}/{action}") @Transactional public Map<String,Boolean> visibility(@PathVariable String id,@PathVariable String action,Authentication auth){if(!Set.of("delete","restore").contains(action))throw new ResponseStatusException(HttpStatus.NOT_FOUND);db.queryForObject("SELECT id FROM demo_data_lock WHERE id=1 FOR UPDATE",Integer.class);row("announcement",id);boolean deleted=action.equals("delete");db.update("UPDATE demo_publications SET deleted=? WHERE kind='announcement' AND id=?",deleted,id);audit(auth,deleted?"ELIMINAR_COMUNICADO":"RESTAURAR_COMUNICADO",id);return Map.of("deleted",deleted);}
 private void validateRows(String value,boolean points){if(value.isBlank())return;try{var node=new com.fasterxml.jackson.databind.ObjectMapper().readTree(value);if(!node.isArray()||node.size()>20)throw new IllegalArgumentException();for(var row:node){if(!row.isObject()||row.path(points?"name":"label").asText().isBlank()||!points&&row.path("amount").asText().isBlank())throw new IllegalArgumentException();var keys=points?Set.of("name","address","mapUrl","time"):Set.of("label","amount","deadline");var it=row.fieldNames();while(it.hasNext()){String k=it.next();if(!keys.contains(k)||!row.get(k).isTextual()||row.get(k).asText().length()>500)throw new IllegalArgumentException();}String url=row.path("mapUrl").asText();if(!url.isBlank()&&!BulkDataService.https(url))throw new IllegalArgumentException();String time=row.path("time").asText();if(!time.isBlank()){if(!time.matches("[0-9]{2}:[0-9]{2}"))throw new IllegalArgumentException();java.time.LocalTime.parse(time);}String date=row.path("deadline").asText();if(!date.isBlank())java.time.LocalDate.parse(date);String amount=row.path("amount").asText();if(!amount.isBlank()&&(!amount.matches("[0-9]{1,9}")||Long.parseLong(amount)>100000000))throw new IllegalArgumentException();}}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Revisa puntos, horarios y valores.");}}
 private void audit(Authentication auth,String action,String id){db.update("INSERT INTO demo_audit(id,actor,action,resource_id) VALUES (?,?,?,?)",UUID.randomUUID().toString(),auth.getName(),action,id);}
}
